from pathlib import Path
import json,shutil,hashlib,re

work=Path(__file__).parent;kit=work.parents[1]/'outputs/国风海棠-完整贴纸素材包'
evidence=kit/'evidence';copied={};unresolved=[]
def retain(p):
    p=Path(p)
    if not p.is_file():
        unresolved.append(str(p));return None
    if p.resolve()==(work.parents[1]/'国风海棠.png').resolve():return 'original.png'
    key=str(p.resolve())
    if key in copied:return copied[key]
    dest=Path('evidence/retained-generation-inputs')/(hashlib.sha256(key.encode()).hexdigest()[:8]+'-'+p.name)
    (kit/dest).parent.mkdir(exist_ok=True);shutil.copy2(p,kit/dest);copied[key]=str(dest)
    return str(dest)

def rewrite(v,subset,field=''):
    if isinstance(v,dict):return {k:rewrite(x,subset,k) for k,x in v.items()}
    if isinstance(v,list):return [rewrite(x,subset,field) for x in v]
    if not isinstance(v,str):return v
    if v.startswith('/Users/'):
        return retain(v) or ('历史文件未入包：'+Path(v).name+'；仅过程记录，无运行依赖')
    if '/Users/' in v and field in ['native_output_hint','output_hint']:
        # Output hints hold machine locations. Preserve image evidence with relative names.
        paths=re.findall(r'/Users/[^\s`\"\']+\.png',v)
        for p in paths:v=v.replace(p,retain(p) or ('历史原生结果：'+Path(p).name))
        return v
    if subset and field in ['source_crop','reference_image_path','generated_output','reference','reference_file','ref','refs','referenced_image_paths'] and not (kit/v).exists():
        p=work/subset/v
        if p.is_file():return retain(p)
    return v

for f in evidence.glob('*.json'):
    subset=next((s for s in ['left','right','foreground','central'] if f.name.startswith(s+'-')),None)
    d=rewrite(json.loads(f.read_text()),subset)
    f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
(evidence/'过程证据说明.txt').write_text('本目录保存补绘、分割和清晰度修复的提示词与输入证据。路径相对素材包根目录。\n这些记录不参与游戏运行；当前最终贴纸、坐标和覆盖顺序只读取manifest.json。历史生成图可能是修改前的一版，不能据此覆盖当前stickers。\n原始图片保持original.png，原始可见像素在audit/；实际最终效果为reconstructed.png。\n')
print(json.dumps({'retained_evidence_files':len(copied),'unresolved_count':len(unresolved),'unresolved':unresolved},ensure_ascii=False))

